package main
import("strings";"strconv")
var _=strings.Compare
var _=strconv.Itoa
func solve(x map[string]any) any {out:=[]any{};parts:=func(s string)[]string{return strings.FieldsFunc(s,func(r rune)bool{return r=='/'})};prefix:=parts(x["prefix"].(string));for _,p:=range x["paths"].([]any){ps:=parts(p.(string));ok:=len(ps)>=len(prefix);if ok{for i,k:=range prefix{if ps[i]!=k{ok=false;break}}};if ok{out=append(out,p)}};return out}

